# PARI-free ray class groups of K = Q(sqrt35), O = Z[sqrt35], modulus m = p2^e2 p5 p7 oo1 oo2 (e2 in {2,3}),
# built from the exact sequence 1 -> U/U_{m,1} -> (O/m)^x x {+-}^2 -> Cl_m^+ -> Cl -> 1 with hand inputs:
#   (O/p2^3)^x = <sqrt35> = Z/4 (O/p2^2 = O/(2): <sqrt35> = Z/2), F5^x = <2>, F7^x = <3>, U = <-1, eps = 6+sqrt35>,
#   Cl = Z/2 generated by p13 = (13, 3+sqrt35) [sqrt35 = -3 mod p13], p13^2 = (22+3 sqrt35).
# Elements of Cl_m^+ are pairs (r, e): r in G0 = Z/N2 x Z/4 x Z/6 x Z/2 x Z/2, e in {0,1} (multiple of [p13]),
# modulo the unit image, with 2[p13] = iota(22+3 sqrt35).
import itertools, math, cmath
from fractions import Fraction as Fr
def sgn(a, b):
    """sign of a + b sqrt35 (exact)"""
    if b == 0: return (a > 0) - (a < 0)
    if a == 0: return (b > 0) - (b < 0)
    if (a > 0) == (b > 0): return 1 if a > 0 else -1
    big_a = a*a > 35*b*b
    return (1 if a > 0 else -1) if big_a else (1 if b > 0 else -1)
LOG5 = {1:0, 2:1, 4:2, 3:3}; LOG7 = {1:0, 3:1, 2:2, 6:3, 4:4, 5:5}
LOG2_3 = {(1,1):0, (0,3):1, (1,3):2, (0,1):3}     # a+b sqrt35 mod p2^3 -> log_{sqrt35}; key (a mod 2, (a-b) mod 4)
class Ray:
    def __init__(s, e2=3):
        s.e2 = e2; s.n = [4 if e2 == 3 else 2, 4, 6, 2, 2]
        s.G0 = list(itertools.product(*[range(k) for k in s.n]))
        s.um1 = s.iota(-1, 0); s.ueps = s.iota(6, 1); s.c13 = s.iota(22, 3); s.i13 = s.iota(13, 0)
        U = {tuple([0]*5)}
        while True:
            new = {s.add0(u, g) for u in U for g in (s.um1, s.ueps)} | U
            if new == U: break
            U = new
        s.U = U
        s.rep = {}
        for r in s.G0:
            if r in s.rep: continue
            coset = [s.add0(r, u) for u in U]; m = min(coset)
            for c in coset: s.rep[c] = m
        s.elems = sorted({(s.rep[r], e) for r in s.G0 for e in (0, 1)})
        s.idx = {x: i for i, x in enumerate(s.elems)}
        s.order = len(s.elems)
    def add0(s, x, y): return tuple((a+b) % k for a, b, k in zip(x, y, s.n))
    def neg0(s, x): return tuple((-a) % k for a, k in zip(x, s.n))
    def iota(s, a, b):
        """image of the O-element a + b sqrt35 (a unit at 2,5,7) in G0"""
        assert (a+b) % 2 == 1 and a % 5 and a % 7, (a, b)
        if s.e2 == 3: k2 = LOG2_3[(a % 2, (a-b) % 4)]
        else: k2 = 0 if a % 2 == 1 else 1
        return (k2, LOG5[a % 5], LOG7[a % 7], int(sgn(a, b) < 0), int(sgn(a, -b) < 0))
    def cl(s, r, e=0):
        """canonical class of (r in G0) + e*[p13]"""
        e %= 4
        while e >= 2: r = s.add0(r, s.c13); e -= 2
        return (s.rep[r], e)
    def add(s, x, y): return s.cl(s.add0(x[0], y[0]), x[1]+y[1])
    def neg(s, x):
        return s.cl(s.add0(s.neg0(x[0]), s.neg0(s.c13)) if x[1] else s.neg0(x[0]), x[1])
    def sigma(s, x):
        r, e = x
        r2 = (((-r[0]) % s.n[0]), r[1], r[2], r[4], r[3])   # sqrt35 -> -sqrt35 = (-1)*sqrt35 ; signs swap
        y = s.cl(r2, 0)
        if e:   # sigma(p13) = p13' = (13)/p13  -> iota(13) - [p13]
            y = s.add(y, s.add(s.cl(s.i13, 0), s.neg(s.cl(tuple([0]*5), 1))))
        return y
    def characters(s):
        """all characters as (phi on G0 in Q/Z, phi(p13)); value chi(r,e) = e(phi.r + e*phi13)"""
        out = []
        for phi in itertools.product(*[[Fr(j, k) for j in range(k)] for k in s.n]):
            if any(sum(p*g for p, g in zip(phi, u)) % 1 for u in (s.um1, s.ueps)): continue
            base = sum(p*g for p, g in zip(phi, s.c13)) % 1
            for j in (0, 1): out.append((phi, (base + j)/2))
        return out
    @staticmethod
    def chival(ch, x):
        phi, p13 = ch
        return (sum(p*g for p, g in zip(phi, x[0])) + x[1]*p13) % 1
def is_unit70(a, b): return (a+b) % 2 == 1 and a % 5 != 0 and a % 7 != 0
